if not Ur[Yr]then
local as={}
for bs,cs in pairs(type(Vr[Yr])==Ioe[2044]and Vr[Yr]or{})do
as[bs]=cs
end
for ds,es in pairs(type(Zr.nums)==Ioe[2044]and Zr.nums or{})do
as[ds]=es
