if ls then
hs.dmg=math.max(hs.dmg or 0,ls*gs)
end
if as.crit then
hs.crit=math.max(hs.crit or 0,(tonumber(as.crit)or 0)*gs)
end
Or.aura,Pr=hs,true
elseif Zr.family==Ioe[2225]then
local ms=pb.KW[tostring(Zr.keyword or Ioe[963])]
local ns=tonumber(as.chance)or 1
local ps=tonumber(as.secsSeen)or tonumber(as.secs)or 5
local qs=as.keep or as.keepSeen
local rs=qs and math.min(1,ns*4)or math.min(1,ps*ns/Qr)
if fs then
rs=math.min(rs,ps/60)
end
if ms and ms.kind==Ioe[2215]and not(type(as.shred)==Ioe[2044])then
local ss=tonumber(as.amp)
local ts=Kr and((type(Kr.ampTypes)==Ioe[2044]and Kr.ampTypes[ms.dtype])or(tonumber(Kr.amp)or 0)>0)
if ss and ss>0 and not ts then
Or.fx,Pr=(Or.fx or 0)+ss*V.TYPED_AMP_SHARE*rs*Rr,true
end
elseif ms and(ms.kind==Ioe[2162]or ms.kind==Ioe[2223])then
if not(Kr and((tonumber(Kr.stun)or 0)>0 or(tonumber(Kr.slowTime)or 0)>0))then
Or.stun=(ms.kind==Ioe[2223]and 0.5 or 1)*ps
if as.slow then
Or.slowP,Or.slowT=tonumber(as.slow),ps
end
Pr=true
end
elseif ms and ms.kind==Ioe[2164]then
if not(Kr and(tonumber(Kr.slowTime)or 0)>0)then
Or.slowP,Or.slowT,Pr=tonumber(as.slow)or tonumber(as.slowSeen)or 0.3,ps,true
end
elseif ms and ms.kind==Ioe[2222]then
local us=tonumber(as.dot)or 0
if us>0 and(tonumber(Kr and Kr.dot)or 0)<us*0.5 then
local vs=math.min(1.5,us)*ns
Or.dot,Pr=(Or.dot or 0)+vs,true
if tostring(Zr.keyword)==Ioe[1886]then
Or.burnDot=(Or.burnDot or 0)+vs
