local LD=KD.dmg/KD.cd/KD.hp/KD.speed*(1+(KD.range-1)/2)
for MD,ND in pairs(KD.kinds)do
LD=LD*(1+bb.rogueShare(MD)*ND)
end
if KD.ice>0 then
local OD=bb.rogueShare(Ioe[2178])
LD=LD*(OD+(1-OD)/(1-KD.ice+KD.ice/gb.modFactor(Ioe[2584])))
end
if KD.fly>0 then
LD=LD*(1-KD.fly*0.5)
end
if KD.noCC then
LD=LD*0.95
end
if KD.shroud then
LD=LD*0.9
end
if KD.zap then
LD=LD*0.85
end
return LD/mb.weatherK(JD)
end
