ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(dfb)
local efb=N.session()
local ffb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local gfb={[dfb.uuid]=true,[O.evolveUnit]=true}
for hfb,ifb in ipairs(V.equipped())do
gfb[ifb.uuid]=true
end
for jfb,kfb in ipairs(P.savedTeam or{})do
gfb[kfb]=true
end
for lfb,mfb in ipairs(P.train and P.train.on and P.train.on.base or{})do
gfb[mfb]=true
end
local nfb,ofb={},0
for pfb,qfb in pairs(efb.profile_data.collection.owned_units)do
local rfb=N.Units[qfb.unit_id]
local sfb=rfb and ab.FUSE_RANK[rfb.rarity]
if sfb and sfb<=ffb and not gfb[pfb]then
local tfb=efb.collection:get_unit_by_uuid(pfb)or qfb
if not(qfb._locked or tfb._locked)and not(qfb._equipped_relic or tfb._equipped_relic)then
local ufb,vfb=pcall(N.USC.calculate_xp_gain_from_fuse,dfb,{tfb},efb)
vfb=ufb and tonumber(vfb)or 0
if vfb>0 then
table.insert(nfb,{uuid=pfb,id=qfb.unit_id,xp=vfb,rarity=rfb.rarity})
ofb=ofb+vfb
end
end
end
end
table.sort(nfb,function(wfb,xfb)
if wfb.xp~=xfb.xp then
return wfb.xp<xfb.xp
end
return wfb.uuid<xfb.uuid
end)
local yfb=math.max(0,kb.xpFor(dfb.unit_id,kb.cap(dfb))-(tonumber(dfb.xp)or 0))
local zfb,Afb={},0
for Bfb,Cfb in ipairs(nfb)do
if Afb>=yfb then
break
end
table.insert(zfb,Cfb)
Afb=Afb+Cfb.xp
end
return zfb,Afb,yfb,ofb
end
function ab.fuseXpTarget(Dfb)
