function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==Ioe[963]then
return
end
local Zfb=N.session()
local _fb=ab.fuseXpTarget(Zfb)
if not _fb then
return
end
local agb=V.name(_fb.unit_id)
local bgb,cgb,dgb=ab.xpFodder(_fb)
if dgb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#bgb==0 then
ab.pickNote.autoFuseXp=Ioe[3178]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=Ioe[3179]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local egb,fgb,ggb=0,0,{}
while F.alive and egb<10 and not P.pauseAll do
if egb>0 then
local hgb,igb,jgb=ab.xpFodder(Zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or _fb)
bgb,dgb={},jgb
for kgb,lgb in ipairs(hgb)do
if not ggb[lgb.uuid]then
table.insert(bgb,lgb)
end
end
if dgb<=0 or#bgb==0 then
break
end
end
local mgb={}
for ngb=1,math.min(ab.fuseBatch,#bgb)do
table.insert(mgb,bgb[ngb].uuid)
end
local ogb=tonumber((Zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or _fb).xp)or 0
local pgb=U.now()
local qgb,rgb=F.request(Ioe[3180],Ioe[3181],O.fuseXpUnit,mgb)
if not qgb and(rgb==Ioe[2119]or rgb==Ioe[2118])then
if rgb==Ioe[2118]or fgb>=3 then
break
end
fgb=fgb+1
task.wait(3.5)
continue
end
while U.now()-pgb<5 and(tonumber((Zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or _fb).xp)or 0)<=ogb do
task.wait(0.1)
end
local sgb=tonumber((Zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or _fb).xp)or 0
if sgb>ogb then
egb=egb+1
for tgb,ugb in ipairs(mgb)do
ggb[ugb]=true
end
cb.add(string.format(Ioe[3182],#mgb,agb),#mgb,Ioe[3183],string.format(Ioe[3184],U.fmt(sgb-ogb)))
F.log(1,Ioe[2549],string.format(Ioe[3185],#mgb,agb,U.fmt(sgb-ogb),kb.level(Zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or _fb)))
elseif#mgb>20 then
ab.fuseBatch=20
F.log(1,Ioe[2549],string.format(Ioe[3186],#mgb,tostring(F.gameSaid(pgb)or(qgb and rgb)or Ioe[2579])))
else
local vgb=F.gameSaid(pgb)
ab.pickNote.autoFuseXp=Ioe[3187]..tostring(vgb or(qgb and rgb)or Ioe[2579])..Ioe[3188]
F.log(1,Ioe[2549],Ioe[3189]..tostring(vgb or(qgb and rgb)or Ioe[2579]))
F.backoff(Ioe[3180],1800)
break
end
end
end
