local svb=rvb and rvb._equipped_relic and kvb.inventory:get_item_by_uuid(rvb._equipped_relic)
if svb and svb.item_id and(N.Items[svb.item_id]or{}).unique_equip then
table.insert(ovb,{uuid=qvb,u=rvb,kind=svb.item_id,relic=rvb._equipped_relic,k=(lvb[qvb]and 1e12 or 0)+kb.score(rvb)})
end
