P.relicOff[xvb.uuid]=xvb.relic
F.log(1,Ioe[3093],string.format(Ioe[3552],V.name(xvb.u.unit_id),yvb,V.name(vvb[xvb.kind])))
else
F.log(1,Ioe[3093],string.format(Ioe[3553],V.name(xvb.u.unit_id),yvb,tostring(Avb)))
