end
end
W._sigAt=nil
if awb then
F.log(1,Ioe[3093],Ioe[3560].. #Ovb..Ioe[3561]..tostring(Pvb))
else
local swb={}
for twb,uwb in ipairs(V.equipped())do
table.insert(swb,V.name(uwb.id))
end
F.log(1,Ioe[3093],Ioe[3562]..tostring(Pvb)..Ioe[3563]..table.concat(swb,Ioe[2157])..Ioe[3564]..table.concat(bwb,Ioe[2420]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local vwb,wwb={},{}
for xwb,ywb in ipairs(V.equipped())do
wwb[ywb.uuid]=true
end
for zwb,Awb in ipairs(P.savedTeam or{})do
if not wwb[Awb]and N.session().collection:get_unit_by_uuid(Awb)then
table.insert(vwb,Awb)
end
end
local Bwb=0
for Cwb,Dwb in ipairs(vwb)do
if#V.equipped()>=6 then
break
end
F.request(Ioe[3091],Ioe[3092],Dwb)
task.wait(0.8)
local Ewb=U.now()
while U.now()-Ewb<3 and#V.equipped()<math.min(6,Bwb+1+(6- #vwb))do
task.wait(0.25)
