end
function ab.unitLabSafe(hxb)
if O.unitLab==false or type(hxb)~=Ioe[2044]or not ab.LAB.KINDS[hxb.kind]or hxb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==Ioe[2044]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=Ioe[969]then
