return
end
P.unitLab=type(P.unitLab)==Ioe[2044]and P.unitLab or{}
local rxb=P.unitLab
rxb.tried=type(rxb.tried)==Ioe[2044]and rxb.tried or{}
rxb.seen=(tonumber(rxb.seen)or 0)+1
if rxb.seen%ab.LAB.EVERY~=0 then
return
end
local sxb=N.session()
local txb=V.equipped()
if not sxb or#txb<2 then
return
end
local uxb={}
for vxb,wxb in ipairs(txb)do
uxb[wxb.uuid]=true
uxb[wxb.id]=true
end
local xxb,yxb,zxb
for Axb,Bxb in pairs(sxb.profile_data.collection.owned_units)do
local Cxb=Bxb.unit_id
if not uxb[Axb]and not uxb[Cxb]and N.Units[Cxb]and not V.isFarm(Cxb)and not V.allyBuff(Cxb)and os.time()-(tonumber(rxb.tried[Cxb])or 0)>ab.LAB.AGAIN then
local Dxb=ab.unitEvidence(Cxb)
if Dxb<ab.LAB.MIN_EVIDENCE then
local Exb=sxb.collection:get_unit_by_uuid(Axb)or Bxb
local Fxb=kb.score(Exb)
if Fxb>0 and(not xxb or Dxb<yxb or(Dxb==yxb and Fxb>zxb))then
xxb,yxb,zxb={uuid=Axb,id=Cxb,u=Exb},Dxb,Fxb
end
end
end
end
if not xxb then
return
end
local Gxb,Hxb
for Ixb,Jxb in ipairs(txb)do
if not V.isFarm(Jxb.id)and not V.allyBuff(Jxb.id)and Jxb.uuid~=O.evolveUnit then
local Kxb=kb.score(Jxb.u)
if not Gxb or Kxb<Hxb then
Gxb,Hxb=Jxb,Kxb
end
end
end
if not Gxb then
return
end
rxb.tried[xxb.id]=os.time()
local Lxb=0
for Mxb in pairs(rxb.tried)do
Lxb=Lxb+1
if Lxb>300 then
rxb.tried[Mxb]=nil
end
end
local Nxb,Oxb=gb.levelFor(qxb)
if not Nxb then
return
end
local Pxb=gb.info(Nxb,qxb.key,Oxb,qxb.mod or W.ldMod(Nxb)or W.levelMod(qxb.level))
local Qxb={}
for Rxb,Sxb in ipairs(txb)do
table.insert(Qxb,Sxb.uuid==Gxb.uuid and xxb.u or Sxb.u)
end
local Txb,Uxb=pcall(gb.run,Pxb,gb.teamFrom(Qxb,Pxb.map),{hpMul=1.1})
local Vxb=Txb and type(Uxb)==Ioe[2044]and(Uxb.won or(Pxb.infinite and(tonumber(Uxb.wave)or 0)>=0.8*W.infReach(qxb.key)))
if not Vxb then
F.log(2,Ioe[3575],string.format(Ioe[3576],V.name(xxb.id),qxb.label))
return
end
local Wxb={}
for Xxb,Yxb in ipairs(txb)do
table.insert(Wxb,Yxb.uuid==Gxb.uuid and xxb.uuid or Yxb.uuid)
end
if ab.equipTeam(Wxb,Ioe[3577]..V.name(xxb.id))then
rxb.now={id=xxb.id,out=Gxb.id,key=qxb.key,at=os.time(),ev=yxb}
F.log(1,Ioe[3575],string.format(Ioe[3578],V.name(xxb.id),V.name(Gxb.id),qxb.label,yxb))
F.saveNow()
end
end
function ab.unitLabDone(Zxb)
