function eb.upgradeGain(GBb,HBb,IBb,JBb,KBb,LBb)
local MBb,NBb=HBb[IBb],HBb[IBb+1]
local OBb=(MBb.cd>0 and MBb.damage/MBb.cd or 0)
local PBb=(NBb.cd>0 and NBb.damage/NBb.cd or 0)*V.aoe(NBb.atk,NBb.range)/math.max(0.3,V.aoe(MBb.atk,MBb.range))
local QBb=OBb>0 and GBb*(PBb/OBb-1)or(LBb or 0)
local RBb=HBb[IBb+2]
if RBb and IBb+1<HBb.max and RBb.cd>0 and NBb.cd>0 and OBb>0 then
local SBb=GBb*((RBb.damage/RBb.cd)/OBb-1)
local TBb=JBb+RBb.cost*KBb
if SBb/TBb>QBb/JBb then
QBb=QBb+(SBb/TBb*JBb-QBb)*0.5
end
end
local UBb=(NBb.range or 0)>(MBb.range or 0)and(1+((NBb.range-MBb.range)/math.max(1,MBb.range)))or 1
return math.max(0,QBb)*UBb
end
function eb.dpsFor(VBb,WBb)
if WBb<=0 then
return 0
end
local XBb={}
for YBb,ZBb in ipairs(VBb)do
if not ZBb.farm and not ZBb.grif and ZBb.gain>0 then
table.insert(XBb,ZBb)
end
end
table.sort(XBb,function(_Bb,aCb)
return _Bb.gain/_Bb.cost>aCb.gain/aCb.cost
end)
local bCb,cCb=0,0
for dCb,eCb in ipairs(XBb)do
if WBb<=0 then
break
end
cCb=eCb.gain/eCb.cost
local fCb=math.min(1,WBb/eCb.cost)
bCb=bCb+eCb.gain*fCb
WBb=WBb-eCb.cost*fCb
end
return bCb+math.max(0,WBb)*cCb*0.7
end
function eb.shieldDps(gCb,hCb,iCb,jCb,kCb,lCb,mCb)
if(jCb or 0)<=0 or(gCb or 0)<=0 or(kCb or 0)<=0 then
return gCb or 0
end
hCb,iCb,lCb=math.max(0.3,hCb or 2),math.max(1,iCb or 1),lCb or 1
local nCb=gCb*lCb*hCb/iCb
return kCb*iCb/((jCb/math.max(1,mCb or 1)+math.max(1,kCb/nCb))*hCb)/lCb
end
function eb.shieldGain(oCb,pCb,qCb,rCb,sCb,tCb,uCb,vCb)
local wCb,xCb=V.attackInfo(pCb.atk,pCb.range),V.attackInfo(rCb.atk,rCb.range)
local yCb=eb.shieldDps(oCb,(tonumber(pCb.cd)or 2)*(uCb or 1),wCb.n,sCb,tCb,vCb,wCb.hits)
local zCb=eb.shieldDps(qCb,(tonumber(rCb.cd)or 2)*(uCb or 1),xCb.n,sCb,tCb,vCb,xCb.hits)
local ACb=math.max(0,((tonumber(rCb.range)or 0)-(tonumber(pCb.range)or 0))/math.max(1,tonumber(pCb.range)or 1))
return math.max(0,zCb-yCb)+yCb*ACb
end
function eb.shieldWork(BCb,CCb,DCb,ECb,FCb,GCb,HCb,ICb,JCb)
if(ECb or 0)<=0 then
return 0
end
local KCb=3*ECb*(FCb or 1)/math.max(1,GCb or 20)
if(DCb or 0)>=KCb then
return 0
end
return math.max(1,BCb or 1)*math.max(1,JCb or 1)/math.max(0.3,CCb or 2)*math.min(HCb or 0,ICb or 0)
end
function eb.holdGain(LCb,MCb,NCb,OCb)
if not LCb or(MCb or 0)<=0 then
return 0
end
local PCb,QCb=tonumber(LCb.stun)or 0,tonumber(LCb.slowTime)or 0
if PCb<=0 and QCb<=0 then
return 0
end
local RCb,SCb=PCb>0 and PCb or QCb,PCb>0 and 1 or(tonumber(LCb.slowPct)or 0.3)
local TCb=SCb*RCb/(RCb+(tonumber(LCb.ccCd)or 8))
local UCb=TCb/math.max(0.1,1-TCb)
return MCb*UCb*U.clamp(NCb or 0.5,0,1)*math.min(1,(tonumber(LCb.n)or 1)/2)/(1+(OCb or 0))
end
function eb.bleedGain(VCb,WCb,XCb,YCb)
if(VCb or 0)<=0 then
return 0
end
local ZCb=WCb or 0
for _Cb,aDb in ipairs(XCb or{})do
ZCb=math.max(ZCb,(tonumber(aDb.hp)or 0)*0.5)
end
return VCb*ZCb*(YCb and 0.5 or 1)
end
function eb.bleedShare(bDb,cDb,dDb,eDb)
if bDb<=0 or not cDb then
return 0
end
if eDb then
return cDb==0 and bDb or bDb/(cDb+1)
end
return dDb<cDb and bDb/(cDb-dDb)or 0
end
function eb.keepsUp(fDb,gDb,hDb,iDb,jDb)
local kDb=fDb.coming
if not(kDb and#kDb>0 and fDb.waveSec)then
return true
end
local lDb=fDb.eff or 1
local mDb=fDb.money-hDb
local nDb=(fDb.teamDps or 0)*(fDb.shieldK or 1)+(iDb or 0)*lDb+eb.dpsFor(gDb,math.max(0,mDb))*lDb
local oDb=(fDb.farmNow or 0)+(jDb or 0)
local pDb=(fDb.roadSec or 130)*U.clamp(fDb.cover or 0.6,0.1,1)
