for bOb=1,#ZNb do
for cOb=bOb+1,#ZNb do
for dOb,eOb in ipairs(RNb[YNb][ZNb[bOb]])do
for fOb,gOb in ipairs(RNb[YNb][ZNb[cOb]])do
local hOb,iOb=eOb.X-gOb.X,eOb.Z-gOb.Z
local jOb=hOb*hOb+iOb*iOb
if jOb<_Nb then
_Nb=jOb
end
end
end
end
end
if#ZNb>=2 then
