if wOb~=mOb and wOb.mask and not(wOb.e and wOb.e.farm)and not wOb.buff then
for xOb,yOb in ipairs(pOb)do
local zOb=wOb.mask.lanes and wOb.mask.lanes[yOb]
for AOb=1,gb.BINS do
if(zOb and zOb[AOb])or(not wOb.mask.lanes and wOb.mask[AOb])then
sOb[yOb]=sOb[yOb]+1
end
end
end
end
end
local BOb=pOb[1]
for COb,DOb in ipairs(pOb)do
if sOb[DOb]<sOb[BOb]then
