function gb.footMove1()
local uQb={}
local function vQb(wQb)
if uQb[wQb]==nil then
local xQb,yQb=0,0
local zQb=P.learn[wQb]
if zQb and tonumber(zQb.n)and zQb.n>=1 then
local AQb=tonumber(zQb.eff)or 1
