xQb,yQb=math.log(math.max(0.01,AQb))*zQb.n,zQb.n
end
local BQb,CQb=V.hiveEff(wQb,true)
if BQb then
xQb,yQb=xQb+math.log(math.max(0.01,BQb))*CQb,yQb+CQb
end
uQb[wQb]=V.nudgeFrom(xQb,yQb)
end
