end
local DQb=0
for EQb,FQb in pairs(P.simCal or{})do
for GQb,HQb in ipairs({Ioe[3752],Ioe[3753]})do
for IQb,JQb in pairs(type(FQb)==Ioe[2044]and type(FQb[HQb])==Ioe[2044]and FQb[HQb]or{})do
if type(JQb)==Ioe[2044]and tonumber(JQb.k)and not tonumber(JQb.nu)then
JQb.nu=vQb(IQb)
DQb=DQb+1
end
end
end
end
for KQb in pairs(P.learn or{})do
vQb(KQb)
end
for LQb,MQb in pairs(P.learn or{})do
