local zRb,ARb={},{}
for BRb,CRb in pairs(P.simCal)do
local DRb=BRb~=Ioe[2071]and not tostring(BRb):find(Ioe[3734],1,true)and type(CRb)==Ioe[2044]and type(CRb.dmgK)==Ioe[2044]and CRb.dmgK or nil
