gb.DMG_SOLVE_LO,gb.DMG_SOLVE_HI,gb.DMG_SOLVE_TRIES=0.1,3,6
function gb.dmgSolve(bSb,cSb,dSb,eSb,fSb)
local function gSb(hSb)
local iSb=table.clone(bSb)
iSb.dmgMul,iSb._dk=hSb,nil
local jSb,kSb=pcall(gb.runRaw,iSb,cSb,dSb)
if not(jSb and type(kSb)==Ioe[2044])then
