for aTb=1,#gb.DMG_BANDS do
local bTb=MSb[tostring(aTb)]
if type(bTb)==Ioe[2044]and tonumber(bTb.k)and(tonumber(bTb.n)or 0)>0 and math.abs(aTb-XSb)<_Sb then
