local jTb=type(MSb[tostring(hTb)])==Ioe[2044]and MSb[tostring(hTb)]or nil
local kTb=(jTb and tonumber(jTb.k))or gb.dmgK(zSb,iTb)
local lTb=dTb[hTb]
if hTb<PSb then
