if vhc and whc and whc.p then
local xhc,yhc=pcall(gb.styleP,whc,whc.zone==false and Ioe[3801]or(whc.zone and Ioe[3737]or nil))
uhc=(uhc*2+(xhc and yhc or whc.p))/3
