function jb.pick(kic)
local lic,mic=jb.curses(kic),jb.lives(kic)
local nic=jb.res(kic)
local oic=jb.rooms(kic)
local pic={}
for qic,ric in ipairs(oic)do
table.insert(pic,tostring(ric.r._r))
end
local sic=table.concat(pic,Ioe[2908])..string.format(Ioe[3967],mic,nic,lic,W.teamSig())
if jb._pick and jb._pick.sig==sic then
return jb._pick.x
end
local tic,uic,vic
for wic,xic in ipairs(oic)do
local yic=jb.roomValue(xic,nic)
local zic,Aic
for Bic,Cic in ipairs(jb.after(kic,xic.choice))do
local Dic=jb.roomValue(Cic,nic)
if not zic or Dic>zic then
zic,Aic=Dic,Cic
end
end
local Eic,Fic=jb.winP(xic)
local Gic=Fic~=nil and Fic.won==false
local Hic=mic>=3 and 1 or(mic==2 and 2 or 6)
