end
if not xic.blocked then
if Gic then
if not uic or xic.score>uic.score then
uic=xic
end
elseif not tic or xic.score>tic.score then
tic=xic
end
end
if not vic or xic.score>vic.score then
vic=xic
end
end
if tic and uic and uic.oldScore>tic.score then
F.log(1,Ioe[3968],string.format(Ioe[3969],jb.roomName(uic),tostring(uic.sim and uic.sim.margin or Ioe[2280]),jb.roomName(tic)))
end
tic=tic or uic or vic
jb._pick={sig=sic,x=tic,rooms=oic}
