_kc[alc]=blc-(Kkc.items[alc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Xkc<Okc,gems=Ykc.gems-Kkc.gems,luck=jb.luck(zkc),paid=Zkc,items=_kc})
while#P.dg.pay>60 do
