end
jb.note(string.format(Ioe[4009],Gkc,Hkc,Akc and Ioe[4010]or(Ekc<=1 and Ioe[4011]or Ioe[4012]),jb.luck(zkc),(tonumber(N.cur(Ioe[2109]))or 0)-Jkc))
