function bb.buildPath()
bb.samples={}
local ipc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not ipc then
return
end
for jpc,kpc in pairs(ipc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[jpc.Name])then
local lpc={}
for mpc,npc in ipairs(kpc.points or{})do
table.insert(lpc,npc.part.Position)
end
local opc=0
for ppc=2,#lpc do
opc=opc+(lpc[ppc]-lpc[ppc-1]).Magnitude
end
local qpc=0
for rpc=2,#lpc do
local spc,tpc=lpc[rpc-1],lpc[rpc]
local upc=(tpc-spc).Magnitude
local vpc=math.max(1,math.floor(upc/2))
for wpc=0,vpc-1 do
local xpc=spc:Lerp(tpc,wpc/vpc)
table.insert(bb.samples,{pos=xpc,prog=(qpc+upc*wpc/vpc)/math.max(1,opc),lane=jpc.Name})
end
qpc=qpc+upc
end
if lpc[#lpc]then
table.insert(bb.samples,{pos=lpc[#lpc],prog=1,lane=jpc.Name})
end
end
end
pcall(bb.readHidden,ipc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local ypc=tonumber(bb.ld and bb.ld._portal_lanes)
local zpc=gb.laneList(bb.samples)
if ypc and ypc>=1 and zpc and#zpc>ypc then
bb.laneWant=ypc
end
bb.laneTotal=zpc and#zpc or 1
bb.countLanes()
end
function bb.readHidden(Apc)
local Bpc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Bpc)~=Ioe[2044]or not next(Bpc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Cpc
for Dpc,Epc in pairs(Apc)do
if Bpc[Dpc.Name]and type(Epc.points)==Ioe[2044]and#Epc.points>=2 then
local Fpc={}
for Gpc,Hpc in ipairs(Epc.points)do
Fpc[Gpc]=U.flat(Hpc.part.Position)
end
local Ipc={}
for Jpc,Kpc in ipairs(bb.samples)do
local Lpc=tostring(Kpc.lane)
Ipc[Lpc]=Ipc[Lpc]or{}
table.insert(Ipc[Lpc],Kpc)
end
local Mpc,Npc
for Opc,Ppc in pairs(Ipc)do
local Qpc=0
for Rpc=1,#Fpc,math.max(1,math.floor(#Fpc/20))do
local Spc=math.huge
for Tpc,Upc in ipairs(Ppc)do
local Vpc=(U.flat(Upc.pos)-Fpc[Rpc]).Magnitude
if Vpc<Spc then
Spc=Vpc
end
end
Qpc=Qpc+Spc
end
if not Npc or Qpc<Npc then
Mpc,Npc=Opc,Qpc
end
end
local Wpc,Xpc,Ypc,Zpc,_pc,aqc={},nil,nil,nil,0,0
for bqc,cqc in ipairs(Fpc)do
local dqc,eqc=nil,math.huge
for fqc,gqc in ipairs(Ipc[Mpc])do
local hqc=(U.flat(gqc.pos)-cqc).Magnitude
if hqc<eqc then
eqc,dqc=hqc,gqc.prog
end
end
aqc=math.max(aqc,eqc)
if Ypc then
local iqc=dqc-Ypc
local jqc=(iqc>0.002 and 1)or(iqc< -0.002 and-1)or Zpc
if Zpc and jqc and jqc~=Zpc then
table.insert(Wpc,math.floor(Ypc*1000+0.5)/1000)
end
Zpc,_pc=jqc or Zpc,_pc+math.abs(iqc)
else
Xpc=dqc
end
Ypc=dqc
if bqc%50==0 then
task.wait()
end
end
if Ypc and aqc<=8 then
table.insert(Wpc,math.floor(Ypc*1000+0.5)/1000)
Cpc=Cpc or{}
Cpc[Dpc.Name]={from=math.floor((Xpc or 0)*1000+0.5)/1000,len=math.floor(_pc*1000+0.5)/1000,turns=Wpc,road=Mpc}
end
end
end
if not Cpc then
return
end
local kqc=bb.ld.map
P.maps[kqc]=P.maps[kqc]or{}
local lqc=P.maps[kqc].hidden
P.maps[kqc].hidden=Cpc
if type(lqc)~=Ioe[2044]then
for mqc,nqc in pairs(Cpc)do
F.log(1,Ioe[2713],string.format(Ioe[4102],mqc,nqc.len,tostring(nqc.road),math.floor((#nqc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local oqc,pqc,qqc={},0,0
for rqc,sqc in ipairs(bb.samples)do
local tqc=tostring(sqc.lane)
if not oqc[tqc]then
pqc=pqc+1
end
oqc[tqc]=(oqc[tqc]or 0)+1
qqc=qqc+1
end
bb.laneCount={n=pqc,by=oqc,avg=pqc>0 and qqc/pqc or 1}
if pqc>=2 then
local uqc,vqc=pcall(gb.laneSep,bb.samples)
local wqc=P.maps[bb.mapKey()]
if uqc and vqc and type(wqc)==Ioe[2044]then
wqc.sep=vqc
end
end
end
