bb.probe.Size=Vector3 .new(Atc*2,2.5,Atc*2)
bb.probe.CFrame=CFrame.new(ztc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Btc=U.flat(ztc)
local Ctc=bb.grifZone
if Ctc and type(wtc)==Ioe[2044]and wtc.id~=V.GRIF.egg and not V.sacFodder(wtc.id)and(Btc-Ctc.p).Magnitude<=Ctc.r+1.5 then
return nil
end
for Dtc,Etc in ipairs(bb.mine or{})do
local Ftc=Etc:FindFirstChild(Ioe[4138])
local Gtc=Ftc and Ftc.Position or Etc:GetPivot().Position
local Htc=Ftc and math.max(Ftc.Size.X,Ftc.Size.Z)/2 or 1.5
if(Btc-U.flat(Gtc)).Magnitude<Atc+Htc then
return nil
end
end
if not xtc then
for Itc,Jtc in ipairs(bb.blockers())do
if(Btc-Jtc.p).Magnitude<Atc+Jtc.r then
return nil
end
end
end
return ztc
end
function bb.buildCandidates()
bb.cands={}
local Ktc={}
for Ltc=1,#bb.samples,3 do
local Mtc=bb.samples[Ltc]
local Ntc=bb.samples[math.min(#bb.samples,Ltc+1)]
local Otc=U.flat(Ntc.pos-Mtc.pos)
if Otc.Magnitude<0.01 then
Otc=Vector3 .new(1,0,0)
end
Otc=Otc.Unit
local Ptc=Vector3 .new(-Otc.Z,0,Otc.X)
for Qtc,Rtc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Stc,Ttc in ipairs({1,-1})do
local Utc=Mtc.pos+Ptc*Rtc*Ttc
local Vtc=string.format(Ioe[4135],math.floor(Utc.X/1.5),math.floor(Utc.Z/1.5))
if not Ktc[Vtc]then
Ktc[Vtc]=true
table.insert(bb.cands,Utc)
end
end
end
end
end
function bb.coverage(Wtc,Xtc)
local Ytc={}
for Ztc,_tc in ipairs(Wtc)do
local auc=_tc._stats
if not V.isFarm(auc.id.Value)and auc:FindFirstChild(Ioe[2297])then
table.insert(Ytc,{p=U.flat(_tc:GetPivot().Position),r=auc.range.Value*(V.SUMMONER[auc.id.Value]and V.SUMMONER[auc.id.Value].reach or 1),air=bb.canAir(_tc)})
end
end
local buc,cuc=0,0
if#Ytc>0 then
for duc,euc in ipairs(bb.samples)do
if euc.prog>cuc then
local fuc=U.flat(euc.pos)
for guc,huc in ipairs(Ytc)do
if(fuc-huc.p).Magnitude<=huc.r then
if euc.prog>buc then
buc=euc.prog
end
if huc.air then
cuc=euc.prog
break
end
end
end
end
end
end
local iuc,juc={},bb.laneCount
if juc and juc.n>=2 and#Ytc>0 then
local kuc={}
for luc,muc in ipairs(bb.samples)do
local nuc=U.flat(muc.pos)
for ouc,puc in ipairs(Ytc)do
if(nuc-puc.p).Magnitude<=puc.r then
local quc=tostring(muc.lane)
kuc[quc]=(kuc[quc]or 0)+1
if muc.prog>(iuc[quc]or 0)then
iuc[quc]=muc.prog
end
break
end
end
end
local ruc,suc={},0
for tuc,uuc in pairs(juc.by)do
ruc[tuc]=(kuc[tuc]or 0)/math.max(1,uuc)
suc=math.max(suc,ruc[tuc])
end
bb.laneW={}
for vuc,wuc in pairs(juc.by)do
bb.laneW[vuc]=(juc.avg/math.max(1,wuc))*(1+1.5*(suc>0 and(1-ruc[vuc]/suc)or 0))
end
bb.laneFrac=ruc
else
bb.laneW,bb.laneFrac=nil,nil
end
local xuc,yuc,zuc
if#Ytc>0 then
for Auc,Buc in ipairs(Xtc)do
local Cuc=(bb.laneW and Buc.lane)and(iuc[tostring(Buc.lane)]or 0)or buc
if Buc.hp>0 and Buc.prog>Cuc+0.02 and Buc.prog>(xuc or 0)then
xuc,zuc=Buc.prog,bb.laneW and Buc.lane or nil
end
if Buc.hp>0 and Buc.fly and Buc.prog>cuc+0.02 then
yuc=true
end
end
end
local Duc= #Ytc>0 and(bb.pressure or 0)>=buc-0.08
return{covEnd=buc,airEnd=cuc,leak=xuc,leakLane=zuc,covL=iuc,airLeak=yuc,push=Duc,units= #Ytc}
end
function bb.needLastLine(Euc)
if V.isFarm(Euc.id)or V.allyBuff(Euc.id)or bb.fieldCount()<5 then
return false
end
local Fuc,Guc=0,0
for Huc,Iuc in ipairs(bb.mine or{})do
local Juc=Iuc._stats
if not V.isFarm(Juc.id.Value)and Juc:FindFirstChild(Ioe[2297])then
local Kuc,Luc=U.flat(Iuc:GetPivot().Position),Juc.range.Value
for Muc,Nuc in ipairs(bb.samples)do
if Nuc.prog>=0.85 and(U.flat(Nuc.pos)-Kuc).Magnitude<=Luc then
Fuc=Fuc+1
if bb.canAir(Iuc)then
Guc=Guc+1
end
break
end
end
end
end
return Fuc<2 or(Guc<1 and bb.flyMode()and bb.cardAir(Euc.id))
end
