LMc[MMc]={math.floor(NMc.X*10+0.5)/10,math.floor(NMc.Y*10+0.5)/10,math.floor(NMc.Z*10+0.5)/10}
end
P.mapBook[IMc.key]={spots=LMc,style=IMc.base.style,hp=KMc.hp,n=KMc.n,kills=JMc.kills and math.floor(JMc.kills+0.5)or nil,wave=JMc.wave and math.floor(JMc.wave*10+0.5)/10 or nil,base=KMc.baseWave and math.floor(KMc.baseWave*10+0.5)/10 or nil,label=KMc.label,map=HMc.map,killScore=KMc.kills,at=os.time()}
local OMc={}
for PMc,QMc in pairs(P.mapBook)do
table.insert(OMc,{k=PMc,at=type(QMc)==Ioe[2044]and tonumber(QMc.at)or 0})
end
if#OMc>bb.BOOK_MAX then
table.sort(OMc,function(RMc,SMc)
return RMc.at>SMc.at
end)
for TMc=bb.BOOK_MAX+1,#OMc do
P.mapBook[OMc[TMc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(UMc,VMc,WMc)
if type(UMc)~=Ioe[2044]or UMc.ended then
return
end
UMc.ended=true
if WMc and VMc then
local XMc=bb.bookFor(VMc.info)
if XMc then
XMc.n=UMc.n
F.saveSoon()
elseif UMc.run>0 then
pcall(bb.bookSave,VMc.info,VMc,WMc,UMc)
end
end
if UMc.run>0 then
F.log(1,Ioe[2798],bb.studyWords(UMc))
end
end
function bb.studyReport()
local YMc=bb.info and bb.bookFor(bb.info)
if not YMc then
return nil
end
local ZMc={}
for _Mc,aNc in pairs(YMc.spots)do
if type(aNc)==Ioe[2044]then
ZMc[_Mc]={aNc[1],aNc[3]}
end
end
return{n=YMc.n,kills=YMc.kills,wave=YMc.wave,hp=YMc.hp,spots=ZMc}
end
function bb.studyText()
if O.mapStudy==false then
return Ioe[3114]
end
if F.where==Ioe[2117]and type(bb.study)==Ioe[2044]and not bb.study.ended then
return Ioe[4288]..bb.studyWords(bb.study)
end
local bNc,cNc,dNc=0,nil,0
for eNc,fNc in pairs(type(P.mapBook)==Ioe[2044]and P.mapBook or{})do
if type(fNc)==Ioe[2044]then
bNc=bNc+1
if(tonumber(fNc.at)or 0)>dNc then
cNc,dNc=fNc,tonumber(fNc.at)or 0
end
end
end
if bNc==0 then
return Ioe[4289]
end
return string.format(Ioe[4290],bNc,tostring(cNc.label),tonumber(cNc.n)or 0,cNc.killScore and string.format(Ioe[4224],tonumber(cNc.kills)or 0)or string.format(Ioe[4291],tostring(cNc.wave)))
end
function bb.spotResult(gNc,hNc)
if not(bb.info and bb.info.timeLimit)then
for iNc,jNc in pairs(bb.layoutUsed or{})do
local kNc=bb.spotRec(iNc,jNc,true)
kNc.runs,kNc.wins=(tonumber(kNc.runs)or 0)+1,(tonumber(kNc.wins)or 0)+(gNc and 1 or 0)
end
end
local lNc,mNc=pcall(bb.labRecord,gNc,hNc)
if not lNc then
F.log(1,Ioe[2431],Ioe[4278]..tostring(mNc))
end
local nNc,oNc=pcall(bb.layoutResult,gNc,hNc)
if not nNc then
F.log(1,Ioe[2431],Ioe[4292]..tostring(oNc))
end
if not bb.infinite then
bb.styleRecord(gNc)
end
end
bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(pNc,qNc)
local rNc=bb.bookKey(pNc)
P.layoutRec=type(P.layoutRec)==Ioe[2044]and P.layoutRec or{}
local sNc=P.layoutRec[rNc]
if type(sNc)~=Ioe[2044]then
if not qNc then
return nil
end
sNc={at=os.time()}
P.layoutRec[rNc]=sNc
if U.count(P.layoutRec)>80 then
local tNc,uNc
for vNc,wNc in pairs(P.layoutRec)do
local xNc=type(wNc)==Ioe[2044]and tonumber(wNc.at)or 0
if not uNc or xNc<uNc then
tNc,uNc=vNc,xNc
end
end
P.layoutRec[tNc]=nil
end
end
return sNc
end
function bb.layoutAdd(yNc,zNc,ANc,BNc,CNc)
yNc.runs,yNc.wins=(tonumber(yNc.runs)or 0)+1,(tonumber(yNc.wins)or 0)+(zNc and 1 or 0)
yNc.sec,yNc.wave=type(yNc.sec)==Ioe[2044]and yNc.sec or{},type(yNc.wave)==Ioe[2044]and yNc.wave or{}
if zNc and tonumber(ANc)then
table.insert(yNc.sec,math.floor(ANc+0.5))
end
table.insert(yNc.wave,tonumber(BNc)or 0)
if tonumber(CNc)then
yNc.kills=type(yNc.kills)==Ioe[2044]and yNc.kills or{}
table.insert(yNc.kills,math.floor(tonumber(CNc)))
while#yNc.kills>bb.LAYOUT_KEEP do
table.remove(yNc.kills,1)
end
end
while#yNc.sec>bb.LAYOUT_KEEP do
table.remove(yNc.sec,1)
end
while#yNc.wave>bb.LAYOUT_KEEP do
table.remove(yNc.wave,1)
end
end
function bb.layoutJudge(DNc,ENc,FNc,GNc,HNc)
HNc=HNc or Ioe[4293]
local INc,JNc=tonumber(DNc and DNc.runs)or 0,tonumber(ENc and ENc.runs)or 0
if INc<1 or JNc<bb.LAYOUT_CONTROL then
return nil
end
if GNc and type(DNc.kills)==Ioe[2044]and type(ENc.kills)==Ioe[2044]and#DNc.kills>=1 and#ENc.kills>=bb.LAYOUT_CONTROL then
local KNc,LNc=bb.labMedian(DNc.kills),bb.labMedian(ENc.kills)
if KNc and LNc and KNc<LNc*0.97 and(#DNc.kills>=2 or KNc<LNc*0.85)then
return string.format(Ioe[4294],KNc,LNc,HNc)
end
return nil
end
local MNc,NNc=(tonumber(DNc.wins)or 0)/INc,(tonumber(ENc.wins)or 0)/JNc
if not FNc and NNc>=0.5 then
if MNc+0.25<NNc and(INc>=2 or(MNc==0 and NNc>=0.9 and JNc>=3))then
return string.format(Ioe[4295],tonumber(DNc.wins)or 0,INc,INc==1 and Ioe[963]or Ioe[1890],tonumber(ENc.wins)or 0,JNc,HNc)
end
local ONc,PNc=bb.labMedian(DNc.sec),bb.labMedian(ENc.sec)
if ONc and PNc and ONc>PNc*1.10 and(#DNc.sec>=2 or ONc>PNc*1.25)then
return string.format(Ioe[4296],math.floor(ONc/60),ONc%60,math.floor(PNc/60),PNc%60,HNc)
end
return nil
end
local QNc,RNc=bb.labMedian(DNc.wave),bb.labMedian(ENc.wave)
if QNc and RNc and QNc<RNc-math.max(1,RNc*0.03)and(INc>=2 or QNc<RNc*0.85)then
return string.format(Ioe[4297],QNc,RNc,HNc)
end
return nil
end
function bb.layoutResult(SNc,TNc)
local UNc=bb.info
local VNc=bb.layoutSrc
if not(UNc and VNc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not UNc.timeLimit then
return
end
local WNc=bb.wave()
local XNc=bb.layoutRecFor(UNc,true)
XNc.at=os.time()
local YNc=UNc.timeLimit~=nil
local ZNc=UNc.killScore and true or nil
local _Nc=ZNc and(bb.killsEnd or bb.realKills())or nil
if VNc==Ioe[4263]then
local aOc=bb.bookFor(UNc)
if not aOc then
return
end
aOc.real=type(aOc.real)==Ioe[2044]and aOc.real or{}
bb.layoutAdd(aOc.real,SNc,TNc,WNc,_Nc)
local bOc=aOc.aside==nil and bb.layoutJudge(aOc.real,XNc.own,YNc,ZNc)or nil
if bOc then
aOc.aside={at=os.time(),why=bOc}
F.log(1,Ioe[4203],string.format(Ioe[4298],bOc))
end
elseif VNc==Ioe[3637]then
XNc.hiveUnit=type(XNc.hiveUnit)==Ioe[2044]and XNc.hiveUnit or{}
local cOc=XNc.hiveUnit
bb.layoutAdd(cOc,SNc,TNc,WNc,_Nc)
local dOc=bb.bookFor(UNc)
local eOc=dOc and type(dOc.real)==Ioe[2044]and(tonumber(dOc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local fOc=eOc and dOc.real or XNc.own
local gOc=bb.layoutJudge(cOc,fOc,YNc,ZNc,eOc and Ioe[4299]or nil)
if gOc then
cOc.aside,cOc.why=os.time(),gOc
F.log(1,Ioe[4203],string.format(Ioe[4300],gOc))
elseif(tonumber(cOc.runs)or 0)>=bb.HIVE_TRIALS then
local hOc=fOc and bb.layoutJudge(fOc,cOc,YNc,ZNc,Ioe[4301])
if hOc and dOc and type(bb.hiveUnitPlan)==Ioe[2044]then
for iOc,jOc in pairs(bb.hiveUnitPlan)do
dOc.spots[iOc]=jOc
end
dOc.real={runs=cOc.runs,wins=cOc.wins,sec=cOc.sec,wave=cOc.wave,kills=cOc.kills}
dOc.hive,dOc.aside=os.time(),nil
XNc.hiveUnit=nil
F.log(1,Ioe[4203],string.format(Ioe[4302],hOc))
else
cOc.aside,cOc.why=os.time(),Ioe[4303]
F.log(1,Ioe[4203],Ioe[4304])
end
end
else
XNc[VNc]=type(XNc[VNc])==Ioe[2044]and XNc[VNc]or{}
local kOc=XNc[VNc]
bb.layoutAdd(kOc,SNc,TNc,WNc,_Nc)
if VNc==Ioe[3636]and kOc.aside==nil then
local lOc=bb.layoutJudge(kOc,XNc.own,YNc,ZNc)
if lOc then
kOc.aside,kOc.why=os.time(),lOc
F.log(1,Ioe[4203],string.format(Ioe[4305],lOc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Ioe[4306],Ioe[4307],Ioe[4308],Ioe[4309]}
function bb.controlSpot(mOc,nOc)
if not bb.killZone()then
return nil
end
local oOc=gb.holds
if not oOc(mOc.id)or V.toggleOf(mOc.id)then
return nil
end
local pOc,qOc,rOc,sOc=1,0,0,{}
local tOc=bb.hurtSamples()
for uOc,vOc in ipairs(bb.mine or{})do
local wOc=vOc._stats
local xOc=wOc.id.Value
if wOc:FindFirstChild(Ioe[2297])and not V.isFarm(xOc)and not V.allyBuff(xOc)then
local yOc,zOc=U.flat(vOc:GetPivot().Position),wOc.range.Value
if oOc(xOc)and not V.toggleOf(xOc)then
rOc=rOc+1
table.insert(sOc,{p=yOc,r=zOc})
else
for AOc,BOc in ipairs(tOc)do
if(U.flat(BOc.pos)-yOc).Magnitude<=zOc then
pOc,qOc=math.min(pOc,BOc.prog),math.max(qOc,BOc.prog)
end
end
end
end
end
if qOc<=pOc then
pOc,qOc=0.75,0.98
end
local COc=(nOc or rOc)+1
local DOc=({pOc,qOc,(pOc+qOc)/2,pOc-(qOc-pOc)/2})[COc]
if not DOc then
return nil
end
local EOc=V.range(mOc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local FOc={}
for GOc,HOc in ipairs(bb.cands)do
local IOc,JOc,KOc=U.flat(HOc),0,0
for LOc,MOc in ipairs(tOc)do
if(U.flat(MOc.pos)-IOc).Magnitude<=EOc then
KOc=KOc+1
if math.abs(MOc.prog-DOc)<=0.05 then
JOc=JOc+1
local NOc=U.flat(MOc.pos)
for OOc,POc in ipairs(sOc)do
if(NOc-POc.p).Magnitude<=POc.r then
JOc=JOc-0.5
break
end
end
end
end
end
if JOc>0 then
table.insert(FOc,{pos=HOc,sc=JOc,cov=KOc})
end
if GOc%60==0 then
task.wait()
end
end
table.sort(FOc,function(QOc,ROc)
return QOc.sc>ROc.sc
end)
for SOc,TOc in ipairs(FOc)do
local UOc=bb.valid(TOc.pos,mOc.data)
if UOc then
F.log(1,Ioe[4142],string.format(Ioe[4310],V.name(mOc.id),bb.CONTROL_WORDS[COc],math.floor(DOc*100+0.5)))
return UOc,TOc.cov,DOc
end
if SOc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(VOc)
local WOc,XOc=gb.holds(VOc.id)
if not WOc then
return nil
end
if V.killFed(VOc.id)then
return nil
end
local YOc,ZOc={},0
for _Oc,aPc in ipairs(bb.mine or{})do
local bPc=aPc._stats
local cPc=bPc.id.Value
if bPc:FindFirstChild(Ioe[2297])and not V.isFarm(cPc)and not V.allyBuff(cPc)and cPc~=VOc.id then
local dPc,ePc=pcall(bb.liveDps,aPc,cPc)
ePc=dPc and tonumber(ePc)or 0
if ePc>0 then
table.insert(YOc,{p=U.flat(aPc:GetPivot().Position),r=bPc.range.Value,d=ePc})
ZOc=ZOc+ePc
end
end
end
if#YOc==0 or ZOc<=0 then
return nil
end
local fPc=bb.hurtSamples()
local gPc={}
for hPc,iPc in ipairs(fPc)do
local jPc,kPc=U.flat(iPc.pos),0
for lPc,mPc in ipairs(YOc)do
if(jPc-mPc.p).Magnitude<=mPc.r then
kPc=kPc+mPc.d
end
end
gPc[hPc]=kPc/ZOc
end
local nPc=V.range(VOc.u,math.min(tonumber(XOc)or 0,3,V.rows(VOc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local oPc,pPc,qPc
for rPc,sPc in ipairs(bb.cands)do
local tPc,uPc,vPc=U.flat(sPc),0,0
for wPc,xPc in ipairs(fPc)do
if(U.flat(xPc.pos)-tPc).Magnitude<=nPc then
uPc=uPc+gPc[wPc]
vPc=vPc+1
end
end
if uPc>0 and(not pPc or uPc>pPc)then
local yPc=bb.valid(sPc,VOc.data)
if yPc then
oPc,pPc,qPc=yPc,uPc,vPc
end
end
if rPc%40==0 then
task.wait()
end
end
if not oPc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[VOc.id]then
bb.holdSaid[VOc.id]=true
F.log(1,Ioe[4142],string.format(Ioe[4311],V.name(VOc.id)))
end
return oPc,qPc or 0
end
function bb.bestSpot(zPc,APc,BPc)
if(zPc._grif or zPc.id==V.GRIF.egg)and not BPc and bb.grifOn()then
local CPc,DPc,EPc=pcall(bb.grifSpot,zPc)
if CPc and DPc then
return DPc,EPc
end
if not CPc and ab.every(Ioe[4312],30)then
F.log(1,Ioe[2431],Ioe[4313]..tostring(DPc))
end
if zPc._grif then
return nil,0
end
end
if bb.hybridHill and not zPc._hillTry and type(zPc.data)==Ioe[2044]and zPc.data.hybrid_placement and not zPc.data.hill_unit then
local FPc=setmetatable({data=bb.hillData(zPc.data),_hillTry=true},{__index=zPc})
local GPc,HPc,IPc=pcall(bb.bestSpot,FPc,APc,BPc)
if GPc and HPc then
return HPc,IPc
end
end
if bb.focus and not APc and not BPc and not V.allyBuff(zPc.id)then
local JPc,KPc=bb.focusSpot(zPc)
if JPc then
return JPc,KPc
end
end
if O.fishiFollow and not APc and not BPc then
local LPc,MPc,NPc,OPc,PPc=pcall(bb.drownBoss)
if LPc and MPc and not NPc and PPc and PPc[zPc.id]then
local QPc,RPc,SPc=pcall(bb.drownSpot,zPc,MPc)
if QPc and RPc then
return RPc,SPc
end
end
end
if not APc and not BPc and not(bb.depth and bb.depth.leak)then
local TPc,UPc,VPc=pcall(bb.controlSpot,zPc)
if TPc and UPc then
return UPc,VPc
end
local WPc,XPc,YPc=pcall(bb.holdSpot,zPc)
if WPc and XPc then
return XPc,YPc
end
end
local ZPc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[zPc.id]and not APc and not BPc then
local _Pc=false
for aQc,bQc in ipairs(bb.mine or{})do
local cQc=bQc._stats:FindFirstChild(Ioe[2421])
if cQc and cQc.Value==zPc.uuid then
_Pc=true
break
end
end
if not _Pc then
for dQc,eQc in ipairs(bb.layout[zPc.id])do
local fQc=bb.valid(eQc,zPc.data)
if fQc and bb.sandLine()>0 and bb.cover(fQc,V.range(zPc.u,V.rows(zPc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
fQc=nil
end
if fQc and ZPc then
local gQc,hQc,iQc=false,U.flat(fQc),V.range(zPc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local jQc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for kQc,lQc in ipairs(bb.hurtSamples())do
if lQc.prog>=ZPc+0.02 and(not jQc or tostring(lQc.lane)==jQc)and(U.flat(lQc.pos)-hQc).Magnitude<=iQc then
gQc=true
break
end
end
if not gQc then
fQc=nil
end
end
if fQc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[zPc.id]=fQc
return fQc,bb.cover(fQc,V.range(zPc.u,math.min(3,V.rows(zPc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local mQc=zPc.data
local nQc=bb.depth
local oQc,pQc=bb.hurtSamples(),bb.sandLine()
local qQc
if BPc then
qQc=1
for rQc,sQc in ipairs(bb.mine or{})do
local tQc=sQc._stats
if not V.isFarm(tQc.id.Value)and not(tQc:FindFirstChild(Ioe[2421])and tQc.uuid.Value==zPc.uuid)then
local uQc,vQc=U.flat(sQc:GetPivot().Position),tQc.range.Value
for wQc,xQc in ipairs(oQc)do
if xQc.prog<qQc and(U.flat(xQc.pos)-uQc).Magnitude<=vQc then
qQc=xQc.prog
end
end
end
end
if V.ENTRY[zPc.id]or(bb.studyEntry and zPc.id==bb.trialId)then
qQc=math.min(qQc,pQc+0.1)
end
end
local yQc=(bb.info and tonumber(bb.info.rangeScale))or 1
local zQc=V.range(zPc.u,(nQc and nQc.leak)and 0 or math.min(3,V.rows(zPc.id).max))*yQc
local AQc=(bb.kind==Ioe[2065]or bb.style==Ioe[3737]or bb.style==Ioe[3738])and not APc and not(nQc and nQc.leak)and not V.isFarm(zPc.id)and V.range(zPc.u,V.rows(zPc.id).max)*yQc or nil
local BQc=V.allyBuff(zPc.id)
if bb.killZone()and not APc and not BPc and not BQc and not(nQc and nQc.leak)and not V.isFarm(zPc.id)then
local CQc=AQc or zQc
local DQc={}
for EQc,FQc in ipairs(bb.mine or{})do
local GQc=FQc._stats
local HQc=GQc.id.Value
if not V.isFarm(HQc)and not V.allyBuff(HQc)and GQc:FindFirstChild(Ioe[2297])then
table.insert(DQc,{p=U.flat(FQc:GetPivot().Position),r=GQc.range.Value})
end
end
local IQc={}
for JQc,KQc in ipairs(oQc)do
local LQc=0
local MQc=U.flat(KQc.pos)
for NQc,OQc in ipairs(DQc)do
if(MQc-OQc.p).Magnitude<=OQc.r then
LQc=LQc+1
end
end
IQc[JQc]=LQc
end
local PQc,QQc,RQc
local SQc=0
for TQc,UQc in ipairs(bb.cands)do
local VQc=bb.valid(UQc,mQc)
SQc=SQc+1
if SQc%40==0 then
task.wait()
end
if VQc then
local WQc,XQc,YQc=U.flat(VQc),0,0
for ZQc,_Qc in ipairs(oQc)do
if(U.flat(_Qc.pos)-WQc).Magnitude<=CQc then
YQc=YQc+1
if _Qc.prog>=0.6 then
XQc=XQc+(_Qc.prog-0.5)*(1+IQc[ZQc])
end
end
end
if not QQc or XQc>QQc then
PQc,QQc,RQc=VQc,XQc,YQc
end
end
end
if PQc and QQc>0 then
if not bb.zoneSaid then
bb.zoneSaid=true
F.log(1,Ioe[4142],Ioe[4314])
end
return PQc,RQc or 0
end
end
