if Pfd.prog>=bb.BASE_END then
Kfd=Kfd+Pfd.hp
local Qfd=Mfd[Ofd]
if Qfd then
Lfd=Lfd+math.max(0,Qfd.hp-Pfd.hp)
end
end
end
for Rfd,Sfd in pairs(Mfd)do
if Sfd.prog>=bb.BASE_END and not Nfd[Rfd]then
Lfd=Lfd+Sfd.hp
end
end
if Kfd<=0 then
