local ghd=fhd.id.Value
if not V.isFarm(ghd)and not V.allyBuff(ghd)and fhd:FindFirstChild(Ioe[2297])then
local hhd=tonumber(fhd.range.Value)or 0
local ihd=bb.coverMax[ehd]
if not(ihd and ihd.r==hhd)then
local jhd,khd=U.flat(ehd:GetPivot().Position),-1
for lhd,mhd in ipairs(bb.samples or{})do
if mhd.prog>khd and(U.flat(mhd.pos)-jhd).Magnitude<=hhd then
khd=mhd.prog
end
end
ihd={r=hhd,far=khd}
bb.coverMax[ehd]=ihd
end
table.insert(chd,{far=ihd.far,air=bb.canAir(ehd)})
end
end
if#chd==0 then
return false
end
for nhd,ohd in ipairs(bhd)do
for phd,qhd in ipairs(chd)do
