local jjd=bb.valid(ijd,ajd.data)
gjd=gjd+1
if gjd%40==0 then
task.wait()
end
if jjd then
local kjd,ljd=0,U.flat(jjd)
for mjd,njd in ipairs(bb.hurtSamples())do
if njd.prog>=bjd.prog and(U.flat(njd.pos)-ljd).Magnitude<=cjd then
kjd=kjd+1
end
end
if not fjd or kjd>fjd then
ejd,fjd=jjd,kjd
end
end
end
end
