function nb.K.key(ZVd,_Vd)
local aWd,bWd,cWd=nb.K,nb.Win,Enum.KeyCode
if aWd.cur and not(aWd.cur.obj and aWd.cur.obj.Parent and aWd.shown(aWd.cur.obj))then
aWd.setFocus(nil)
end
if aWd.cur and aWd.cur.listKey and aWd.cur.listKey(ZVd)then
return true
end
if ZVd==cWd.PageUp or ZVd==cWd.PageDown then
local dWd={}
for eWd,fWd in pairs(bWd._tabs)do
table.insert(dWd,{name=eWd,y=fWd.btn.AbsolutePosition.Y,on=fWd.page.Visible})
end
table.sort(dWd,function(gWd,hWd)
return gWd.y<hWd.y
end)
local iWd=1
for jWd,kWd in ipairs(dWd)do
if kWd.on then
iWd=jWd
end
end
iWd=(iWd-1+(ZVd==cWd.PageDown and 1 or-1))% #dWd+1
aWd.setFocus(nil)
bWd:SelectTab(dWd[iWd].name)
return true
end
if ZVd==cWd.Tab or ZVd==cWd.Down or ZVd==cWd.Up then
local lWd=aWd.order()
if#lWd==0 then
return true
end
local mWd=ZVd==cWd.Up or(ZVd==cWd.Tab and _Vd)
local nWd=table.find(lWd,aWd.cur)
if not nWd then
nWd=mWd and#lWd or 1
else
nWd=(nWd-1+(mWd and-1 or 1))% #lWd+1
end
aWd.setFocus(lWd[nWd])
return true
end
if not aWd.cur then
return false
end
if ZVd==cWd.Return or ZVd==cWd.KeypadEnter or ZVd==cWd.Space then
if aWd.cur.activate then
aWd.cur.activate()
end
return true
end
if ZVd==cWd.Left or ZVd==cWd.Right then
if aWd.cur.adjust then
aWd.cur.adjust(ZVd==cWd.Right and 1 or-1)
end
return true
end
if ZVd==cWd.Escape then
aWd.setFocus(nil)
return true
end
return false
end
